BEGIN;
CREATE OR REPLACE FUNCTION public.get_my_commune_subscriptions() RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT ARRAY_AGG(commune ORDER BY commune) FROM public.commune_subscriptions WHERE user_id=auth.uid(); $$;
REVOKE EXECUTE ON FUNCTION public.get_my_commune_subscriptions() FROM public,anon;
GRANT EXECUTE ON FUNCTION public.get_my_commune_subscriptions() TO authenticated;
CREATE OR REPLACE FUNCTION public.get_report_comments(p_report_id uuid) RETURNS TABLE(id uuid,content text,created_at timestamptz,user_id uuid,display_name text,organization_name text,partner_type text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT rc.id,rc.content,rc.created_at,NULL::uuid,'Citoyen'::text,pp.organization_name,pp.partner_type FROM public.report_comments rc JOIN public.reports r ON r.id=rc.report_id AND r.validated=true LEFT JOIN public.partner_profiles pp ON pp.user_id=rc.user_id WHERE rc.report_id=p_report_id AND rc.hidden=false ORDER BY rc.created_at ASC; $$;
CREATE OR REPLACE FUNCTION public.get_transparency_stats() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT jsonb_build_object('total_reports',(SELECT COUNT(*) FROM public.reports WHERE validated=true),'total_resolved',(SELECT COUNT(*) FROM public.reports WHERE validated=true AND status='resolved'),'total_users',(SELECT COUNT(*) FROM public.profiles),'resolution_rate',CASE WHEN (SELECT COUNT(*) FROM public.reports WHERE validated=true)=0 THEN 0 ELSE ROUND(100.0*(SELECT COUNT(*) FROM public.reports WHERE validated=true AND status='resolved')/(SELECT COUNT(*) FROM public.reports WHERE validated=true),1) END,'avg_resolution_hours',(SELECT jsonb_object_agg(service_type,avg_h) FROM (SELECT service_type,ROUND(AVG(EXTRACT(EPOCH FROM(resolved_at-created_at))/3600)::numeric,1) avg_h FROM public.reports WHERE validated=true AND status='resolved' AND resolved_at IS NOT NULL GROUP BY service_type)t),'by_commune',(SELECT jsonb_agg(row ORDER BY row->>'total' DESC) FROM (SELECT jsonb_build_object('commune',commune,'total',COUNT(*),'resolved',COUNT(*) FILTER(WHERE status='resolved'),'resolution_rate',CASE WHEN COUNT(*)=0 THEN 0 ELSE ROUND(100.0*COUNT(*) FILTER(WHERE status='resolved')/COUNT(*),1) END) row FROM public.reports WHERE validated=true GROUP BY commune)t),'monthly',(SELECT jsonb_agg(row ORDER BY row->>'month') FROM (SELECT jsonb_build_object('month',TO_CHAR(DATE_TRUNC('month',created_at),'YYYY-MM'),'total',COUNT(*),'resolved',COUNT(*) FILTER(WHERE status='resolved')) row FROM public.reports WHERE validated=true AND created_at>=NOW()-INTERVAL '12 months' GROUP BY DATE_TRUNC('month',created_at))t),'top_communes',(SELECT jsonb_agg(row) FROM (SELECT jsonb_build_object('commune',commune,'actifs',COUNT(*) FILTER(WHERE status IN ('active','chronic')),'total',COUNT(*)) row FROM public.reports WHERE validated=true GROUP BY commune ORDER BY COUNT(*) FILTER(WHERE status IN ('active','chronic')) DESC LIMIT 5)t)); $$;
CREATE OR REPLACE FUNCTION public.generate_sig_ticket_code(p_commune text,p_created_at timestamptz DEFAULT now()) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ DECLARE v_trigramme text;v_date_str text;v_seq int;v_ticket text; BEGIN SELECT trigramme INTO v_trigramme FROM public.pada_communes WHERE lower(trim(commune))=lower(trim(p_commune)) LIMIT 1;IF v_trigramme IS NULL THEN v_trigramme:=upper(substring(regexp_replace(p_commune,'[^a-zA-Z]','','g') FROM 1 FOR 3));IF length(v_trigramme)<3 THEN v_trigramme:='CIV';END IF;END IF;v_date_str:=to_char(p_created_at AT TIME ZONE 'UTC','YYYYMMDD');SELECT count(*)+1 INTO v_seq FROM public.reports WHERE to_char(created_at AT TIME ZONE 'UTC','YYYYMMDD')=v_date_str;v_ticket:='SIG-'||v_trigramme||'-'||v_date_str||'-'||lpad(v_seq::text,4,'0');RETURN v_ticket;END; $$;
CREATE OR REPLACE FUNCTION public.generate_pada_ticket_code() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ DECLARE v_trigramme text;v_date_str text;v_seq int;v_seq_str text;v_candidate_ticket text;BEGIN IF NEW.ticket_code IS NOT NULL AND NEW.ticket_code<>'' THEN RETURN NEW;END IF;v_trigramme:=public.get_pada_commune_trigramme(NEW.commune);v_date_str:=to_char(coalesce(NEW.created_at,now()) AT TIME ZONE 'UTC','YYYYMMDD');SELECT coalesce(count(*),0)+1 INTO v_seq FROM public.reports WHERE commune=NEW.commune AND to_char(created_at AT TIME ZONE 'UTC','YYYYMMDD')=v_date_str;v_seq_str:=lpad(v_seq::text,4,'0');v_candidate_ticket:='SIG-'||v_trigramme||'-'||v_date_str||'-'||v_seq_str;WHILE EXISTS(SELECT 1 FROM public.reports WHERE ticket_code=v_candidate_ticket) LOOP v_seq:=v_seq+1;v_seq_str:=lpad(v_seq::text,4,'0');v_candidate_ticket:='SIG-'||v_trigramme||'-'||v_date_str||'-'||v_seq_str;END LOOP;NEW.ticket_code:=v_candidate_ticket;IF NEW.pada_commune_code IS NULL OR NEW.pada_commune_code='' THEN NEW.pada_commune_code:=public.get_pada_commune_cadastral_code(NEW.commune);END IF;IF NEW.pada_formatted_address IS NULL OR NEW.pada_formatted_address='' THEN NEW.pada_formatted_address:=coalesce(NEW.pada_street_name,'Voie non dénommée')||' '||NEW.pada_commune_code||', Abidjan - '||NEW.commune||CASE WHEN NEW.quartier IS NOT NULL AND NEW.quartier<>'' THEN ' ('||NEW.quartier||')' ELSE '' END;END IF;RETURN NEW;END; $$;
COMMIT;
